  "item": "DP-24",
  "type": "feature",
  "path": "standard",
  "domains": [
    "ux"
  ],
  "summary": "Move navigation from a top bar to a left sidebar",
  "rationale": "UI-only change to the navigation shell",
  "handoff": false,
  "handoff_reason": null,
  "architecture_change": false,
  "breaking_change": false
}

The breakdown under challenge:

{
  "item": "DP-24",
  "epics": [
    {
      "id": "E1",
      "title": "MainNav becomes a persistent left sidebar",
      "stories": [
        {
          "id": "S1",
          "statement": "MainNav renders as a persistent left sidebar with full labels, replacing the top bar, with app/layout.tsx restructured to host it",
          "domains": [
            "backend"
          ],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "MainNav currently renders as a top bar",
              "when": "the retheme ships",
              "then": "MainNav renders inside a left sidebar container instead of a top bar"
            },
            {
              "id": "AC2",
              "given": "app/layout.tsx's root container currently uses flex-col",
              "when": "the page renders after the retheme",
              "then": "the root container's layout direction is flex-row"
            },
            {
              "id": "AC3",
              "given": "the sidebar is rendered",
              "when": "the page is viewed at any point",
              "then": "the sidebar remains visible with no collapse control and no drawer toggle present in the markup"
            },
            {
              "id": "AC4",
              "given": "the sidebar renders its nav items",
              "when": "the items are displayed",
              "then": "each item shows its full text label rather than an icon-only representation"
            },
            {
              "id": "AC5",
              "given": "MainNav's existing route paths and testids",
              "when": "MainNav moves from the top bar into the sidebar",
              "then": "those route paths and testids are unchanged"
            }
          ]
        },
        {
          "id": "S2",
          "statement": "Sidebar is narrower on mobile than on desktop",
          "domains": [
            "ux"
          ],
          "acceptance_criteria": [
            {
              "id": "AC6",
              "given": "a mobile viewport",
              "when": "the sidebar renders",
              "then": "its width is narrower than the sidebar width rendered at a desktop viewport"
            },
            {
              "id": "AC7",
              "given": "a desktop viewport",
              "when": "the sidebar renders",
              "then": "it uses the full desktop sidebar width"
            }
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Active route gets a glowing highlight",
      "stories": [
        {
          "id": "S3",
          "statement": "MainNav becomes a Client Component so the active route's nav item renders with a glowing highlight",
          "domains": [
            "ux"
          ],
          "acceptance_criteria": [
            {
              "id": "AC8",
              "given": "MainNav's source file",
              "when": "it is inspected",
              "then": "it is declared as a Client Component (e.g. carries a \"use client\" directive)"
            },
            {
              "id": "AC9",
              "given": "the user is viewing a particular route",
              "when": "that route's corresponding nav item renders",
              "then": "it displays a glowing highlight style while the other nav items do not"
            },
            {
              "id": "AC10",
              "given": "a user clicks a nav item in the sidebar",
              "when": "the click is handled",
              "then": "navigation proceeds to the same route it navigated to before the retheme, with no change in click behavior"
            }
          ]
        }
      ]
    }
  ]
}

